SELECT e.symbol, e.id, e.observed_at, e.created_at, e.price, e.delivery_status FROM market_price_event e WHERE (e.symbol='SHIBUSDT' AND e.observed_at BETWEEN '2026-10-12 07:14:55' AND '2026-10-12 07:15:45') OR (e.symbol='XRPUSDT' AND e.observed_at BETWEEN '2026-10-12 03:30:00' AND '2026-10-12 03:30:05') ORDER BY e.symbol, e.observed_at LIMIT 100;
SELECT c.symbol, c.open_time, c.open_price, c.high_price, c.low_price, c.close_price, c.volume, c.number_of_trades, c.closed, c.ingestion_source, c.created_at, c.updated_at FROM candle c WHERE c.symbol='EGLDUSDT' AND c.interval_code='1m' AND c.open_time BETWEEN '2026-10-11 22:40:00' AND '2026-10-11 22:44:00' ORDER BY c.open_time